import json
with open('/app/resources/treasury_bulletin_2021_12.json', 'r') as f:
    data = json.load(f)

doc = data['document']
elements = doc.get('elements', [])

# Search for tables with 'Corporate income' in data
for i, el in enumerate(elements):
    if el.get('type') == 'table':
        if 'data' in el:
            for row in el['data']:
                if row and any('corporate' in str(cell).lower() for cell in row if cell):
                    print(f'Element {i}:')
                    print('  Headers:', el.get('headers', []))
                    print('  Data rows:')
                    for row in el['data']:
                        print('   ', row)
                    print()
                    break
